//go:build fixturegen

// This generator is built only under the fixturegen tag, so it never runs in normal CI and
// never compiles into any binary (and is not linted by the default golangci-lint run, which
// uses no build tags). Regenerate the current schema's release fixture with:
//
//	TMP=<owner-only dir> TEMP=<owner-only dir> \
//	  go test -tags fixturegen -run TestGenerateReleaseFixture ./internal/store/
//
// It writes internal/store/testdata/releases/schema-vNNNN/{store.db,tenant-id.txt} with
// synthetic data only, generated by this release's code (ADR-0012 §4).

package store

import (
	"context"
	"os"
	"path/filepath"
	"strconv"
	"testing"
	"time"

	"github.com/ittcsec/ittcsecscan/internal/model"
)

var fixtureAt = time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

func TestGenerateReleaseFixture(t *testing.T) {
	writeReleaseFixture(t)
}

// writeReleaseFixture creates a tenant with the deterministic fixture key, writes the
// synthetic override, and copies the resulting file and its id into the fixture directory
// for the current schema version.
func writeReleaseFixture(t *testing.T) {
	t.Helper()
	s := openStore(t, Options{DataDir: testDataDir(t), Keys: staticKeys(t, fixtureMasterKey(t))})
	id := createTenant(t, s)
	tn := acquire(t, s, id)
	sid, err := tn.StableID(fixtureNativeID)
	if err != nil {
		t.Fatal(err)
	}
	if err := tn.AddCriticalityOverride(context.Background(), model.CriticalityOverride{
		Entity: model.StableID(sid), Criticality: fixtureCriticality, Actor: fixtureActor, Reason: fixtureReason, At: fixtureAt,
	}); err != nil {
		t.Fatalf("add override: %v", err)
	}
	dir, err := s.layout.dir(id)
	if err != nil {
		t.Fatal(err)
	}
	// Close the store so the database is fully checkpointed before it is copied.
	if err := s.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	db, err := os.ReadFile(dbPath(dir))
	if err != nil {
		t.Fatalf("read generated db: %v", err)
	}
	out := filepath.Join(releasesDir, "schema-v"+pad4(int(prodLatest(t))))
	if err := os.MkdirAll(out, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(out, dbFileName), db, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(out, "tenant-id.txt"), []byte(id.String()+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote fixture %s (tenant %s)", out, id)
}

func pad4(v int) string {
	s := strconv.Itoa(v)
	for len(s) < 4 {
		s = "0" + s
	}
	return s
}
